import { test, expect } from "../../../../core/fixtures/index";
import type { Page, Locator } from "@playwright/test";
import fs from "node:fs";

const SHOT_DIR = "tools/tour2playwright/generated/screenshots/accounting-user-guide-top-vendors-by-credit-value";

// Screenshot the current page with the target element outlined.
async function shot(page: Page, loc: Locator, file: string) {
  try {
    await loc.scrollIntoViewIfNeeded({ timeout: 5000 });
    await loc.evaluate((el) => el.setAttribute("data-t2p", "1"));
    await page.addStyleTag({
      content: '[data-t2p="1"]{outline:3px solid #e01e5a !important;outline-offset:2px !important;}',
    });
  } catch {}
  fs.mkdirSync(SHOT_DIR, { recursive: true });
  await page.screenshot({ path: `${SHOT_DIR}/${file}` });
  try { await loc.evaluate((el) => el.removeAttribute("data-t2p")); } catch {}
}

test.describe("Accounting User Guide - Top Vendors by Credit Value @module:accounting @step:business @e2e", () => {
  // Developer mode adds items to the top bar; at the default 1280px the Accounting menu collapses into the "+" overflow.
  test.use({ viewport: { width: 1600, height: 900 } });

  test("Accounting User Guide - Top Vendors by Credit Value", async ({ page }) => {
    // "Journal Items" only appears in the Accounting menu in developer mode — the recording was made with it on.
    await page.goto("/web?debug=1");

    // The saved browser session can expire — fall back to the login form if we got bounced to it.
    const emailBox = page.getByRole("textbox", { name: "Email" });
    if (await emailBox.isVisible({ timeout: 8_000 }).catch(() => false)) {
      await emailBox.fill(process.env.ADMIN_EMAIL ?? "admin");
      await page.getByRole("textbox", { name: "Password" }).fill(process.env.ADMIN_PASSWORD ?? "admin");
      await page.getByRole("button", { name: "Log in" }).click();
      await page.waitForSelector(".o_main_navbar, .o_home_menu", { state: "visible", timeout: 45_000 });
    }
    // Odoo keeps persistent long-polling/websocket connections open for
    // real-time notifications, so "networkidle" never naturally resolves —
    // bound it explicitly or it silently eats the whole test timeout as its
    // fallback ceiling before its own .catch() ever fires.
    await page.waitForLoadState("networkidle", { timeout: 10_000 }).catch(() => {});

    await test.step("01. Accounting App", async () => {
      const loc = (page.locator("[data-menu-xmlid=\"account_accountant.menu_accounting\"]")).first();
      await loc.waitFor({ state: "visible", timeout: 45000 });
      await shot(page, loc, "step-01.png");
      await loc.click();
    });

    await test.step("02. Accounting Menu", async () => {
      const loc = (page.locator("[data-menu-xmlid=\"account.menu_finance_entries\"]")).first();
      await loc.waitFor({ state: "visible", timeout: 45000 });
      await shot(page, loc, "step-02.png");
      await loc.click();
    });

    await test.step("03. Journal Items", async () => {
      // Recorded as the 2nd menu item (nth-of-type(2)), which is "Purchases" on this build — pick it by its text.
      const loc = (page.locator("a.dropdown-item").filter({ hasText: /^Journal Items$/ })).first();
      await loc.waitFor({ state: "visible", timeout: 45000 });
      await shot(page, loc, "step-03.png");
      await loc.click();
    });

    await test.step("04. Toggle Search Panel", async () => {
      const loc = (page.locator("button.dropdown-toggle.o_searchview_dropdown_toggler")).first();
      await loc.waitFor({ state: "visible", timeout: 45000 });
      await shot(page, loc, "step-04.png");
      await loc.click();
    });

    await test.step("05. Payable", async () => {
      // Recorded by position (nth-of-type(10)) — pick the Payable filter by its text.
      const loc = (page.locator("span.dropdown-item.o_menu_item").filter({ hasText: /^Payable$/ })).first();
      await loc.waitFor({ state: "visible", timeout: 45000 });
      await shot(page, loc, "step-05.png");
      await loc.click();
    });

    await test.step("06. Partner", async () => {
      // Recorded by position (nth-of-type(3)) — pick the Partner group-by by its text.
      const loc = (page.locator(".o_group_by_menu span.dropdown-item").filter({ hasText: /^Partner$/ })).first();
      await loc.waitFor({ state: "visible", timeout: 45000 });
      await shot(page, loc, "step-06.png");
      await loc.click();
    });

    await test.step("07. Credit", async () => {
      // Recorded as the 10th column (nth-of-type(10)), which depends on the visible columns — pick the Credit header by its text.
      const loc = (page.locator("th.o_column_sortable").filter({ hasText: /^Credit$/ })).first();
      await loc.waitFor({ state: "visible", timeout: 45000 });
      // The Filters / Group By panel from steps 4-6 is still open and covers the column headers. A person's
      // first click outside closes it; Playwright would wait forever for the header to be unobstructed.
      await page.keyboard.press("Escape");
      await page.locator('[role="menu"].o_search_bar_menu').waitFor({ state: "hidden", timeout: 10000 }).catch(() => {});
      await shot(page, loc, "step-07.png");
      await loc.click();
    });

    await test.step("08. Credit", async () => {
      // Recorded as the 10th column (nth-of-type(10)), which depends on the visible columns — pick the Credit header by its text.
      const loc = (page.locator("th.o_column_sortable").filter({ hasText: /^Credit$/ })).first();
      await loc.waitFor({ state: "visible", timeout: 45000 });
      await shot(page, loc, "step-08.png");
      await loc.click();
    });

    // The clicks can all "succeed" without the list actually being ranked, so check the result:
    // the Credit totals of the first vendor groups must now run from highest to lowest.
    await test.step("Verify: vendors are ranked by credit, highest first", async () => {
      await expect.poll(async () => {
        const values = await page.evaluate(() => {
          const th = Array.from(document.querySelectorAll("thead th")).find((t) => t.textContent?.trim() === "Credit");
          if (!th) return [] as string[];
          const box = th.getBoundingClientRect();
          return Array.from(document.querySelectorAll("tbody tr.o_group_header")).slice(0, 10).map((row) => {
            const cell = Array.from(row.children).find((c) => {
              const b = c.getBoundingClientRect();
              const x = (b.left + b.right) / 2;
              return x >= box.left && x <= box.right;
            });
            return (cell?.textContent ?? "").trim();
          });
        });
        const nums = values.map((v) => parseFloat(v.replace(/,/g, ""))).filter((n) => !Number.isNaN(n));
        // nums[0] > 0 matters: an unsorted list starts with 0.00 credits, which would otherwise pass "descending" trivially.
        return nums.length > 1 && nums[0] > 0 && nums.every((n, i) => i === 0 || nums[i - 1] >= n);
      }, { timeout: 20000, message: "first vendor groups should be sorted by Credit, highest first (top credit > 0)" }).toBe(true);

      // A step's screenshot is taken BEFORE its click, so also keep the finished ranking for the manual.
      fs.mkdirSync(SHOT_DIR, { recursive: true });
      await page.screenshot({ path: `${SHOT_DIR}/step-08-result.png` });
    });

  });
});
